const fs = await import("node:fs");
const ASAR = "D:\\Users\\jjq21\\AppData\\Local\\Programs\\DeepSeek Harness\\resources\\app.asar";
const fd = fs.openSync(ASAR, "r");
const head = Buffer.alloc(16);
fs.readSync(fd, head, 0, 16, 0);
console.log("first 4 uint32:", head.readUInt32LE(0), head.readUInt32LE(4), head.readUInt32LE(8), head.readUInt32LE(12));
const jsonSize = head.readUInt32LE(12);
const jbuf = Buffer.alloc(jsonSize);
fs.readSync(fd, jbuf, 0, jsonSize, 16);
let dir: any = null;
try { dir = JSON.parse(jbuf.toString("utf8")); console.log("parsed header OK, top keys:", Object.keys(dir)); }
catch (e) { console.log("parse failed:", (e as Error).message.slice(0,200)); }

const dataStart = 16 + jsonSize;
console.log("dataStart:", dataStart);
// sanity: read first file entry and validate
function files(node: any, prefix = "", out: string[] = [], depth = 0): string[] {
  for (const [k, v] of Object.entries<any>(node.files ?? {})) {
    const p = prefix ? prefix + "/" + k : k;
    if (v.files) { if (depth < 6) files(v, p, out, depth + 1); }
    else out.push(p);
  }
  return out;
}
const all = files(dir);
console.log("total files in asar:", all.length);
const de = all.filter(p => p.includes("dsh-web-app") && /\.(js|mjs|json)$/.test(p));
console.log("web-app entries:", de.length);
console.log(de.slice(0, 25).join("\n"));
fs.closeSync(fd);
